    private val reversals=setOf("fujifilm_velvia_100","fujifilm_provia_100f","kodak_ektachrome_100","kodak_kodachrome_64")
    /** User presentation preference only: reversal holes remain white under either selection. */
    fun selectedDefinition(profile:String,negativeWhiteHoles:Boolean):LazyBorderRegistry.Definition {
        val key=profiles[profile] ?: throw IllegalArgumentException("Unknown border profile")
        return if(negativeWhiteHoles || key.physicalStock in reversals)physical.getValue(key.physicalStock)
        else legacyDefinitions.single{it.spec.stock==key.physicalStock && it.spec.holeMatteSrgb==0 && it.spec.sha256==physical.getValue(key.physicalStock).spec.sha256}
    }

